// final class TreeNode { var val: Int; var left, right: TreeNode?; init(_ v: Int) { val = v } }
func serialize(_ root: TreeNode?) -> String {
    var out: [String] = []
    func walk(_ n: TreeNode?) {
        guard let n else { out.append("#"); return }
        out.append(String(n.val)); walk(n.left); walk(n.right)
    }
    walk(root)
    return out.joined(separator: ",")
}

func deserialize(_ data: String) -> TreeNode? {
    var tokens = data.split(separator: ",").makeIterator()
    func build() -> TreeNode? {
        guard let t = tokens.next(), t != "#", let v = Int(t) else { return nil }
        let node = TreeNode(v)
        node.left = build(); node.right = build()
        return node
    }
    return build()
}
